// Subpath barrel for /core-typescript/events
// Consumed by /contracts-typescript wire event classes.
export { BaseEvent } from './types/BaseEvent'
export { BaseDomainEvent } from './types/BaseDomainEvent'
export { BaseIntegrationEvent } from './types/BaseIntegrationEvent'

import { Id } from '../objects/Id'
import { z, type ZodTypeAny } from 'zod'

export const BaseEventSchema = z.object({
	name: z.string(),
	id: z.string(),
	time: z.iso.datetime(),
	payload: z.object(),
})

export abstract class BaseEvent<Payload extends ZodTypeAny = ZodTypeAny> {
	declare static readonly name: string
	readonly name: string
	readonly id: string
	readonly time: string
	readonly payload: z.infer<Payload>

	constructor(payload: z.infer<Payload>) {
		this.name = (this.constructor as { name: string }).name
		this.payload = payload
		this.time = new Date().toISOString()
		this.id = Id.fromSeed(this.serialize()).value
	}

	toJSON() {
		return Object.assign({ name: this.name }, this)
	}

	serialize(): string {
		return JSON.stringify(this)
	}
}

import { BaseEvent } from './BaseEvent'
import { z, type ZodObject, type ZodTypeAny } from 'zod'

export const BaseDomainEventSchema = z.object({
	// Both optional — some events (e.g. BillingWebhookReceivedEvent) carry a
	// computed entityId but no meaningful ownerId; pure "something happened"
	// events may have neither. Events that DO have entity/owner identity
	// (most domain events) still pass them at construction.
	entityId: z.string().optional(),
	ownerId: z.string().optional(),
	payload: z.object(),
})

export type DomainEventSchemaConstraint = ZodObject<{
	entityId: z.ZodOptional<z.ZodString>
	ownerId: z.ZodOptional<z.ZodString>
	payload: ZodTypeAny
}>

export abstract class BaseDomainEvent<EventSchema extends DomainEventSchemaConstraint = typeof BaseDomainEventSchema> extends BaseEvent<
	EventSchema['shape']['payload']
> {
	readonly entityId?: string
	readonly ownerId?: string

	constructor(data: z.infer<EventSchema>) {
		super(data.payload as z.infer<EventSchema['shape']['payload']>)
		this.entityId = data.entityId
		this.ownerId = data.ownerId
	}
}

import { BaseEvent } from './BaseEvent'
import { z, type ZodObject, type ZodTypeAny } from 'zod'

export const BaseIntegrationEventSchema = z.object({
	name: z.string(),
	payload: z.object(),
	ownerId: z.string(),
})

type EventSchemaConstraint = ZodObject<{ name: ZodTypeAny; payload: ZodTypeAny; ownerId: z.ZodString }>

export abstract class BaseIntegrationEvent<EventSchema extends EventSchemaConstraint = typeof BaseIntegrationEventSchema> extends BaseEvent<
	EventSchema['shape']['payload']
> {
	readonly ownerId: string

	constructor(data: Omit<z.infer<EventSchema>, 'name'>) {
		super(data.payload as z.infer<EventSchema['shape']['payload']>)
		this.ownerId = data.ownerId
	}
}

export type Transaction = unknown

export abstract class UnitOfWorkFactory {
	abstract create(): UnitOfWork
}

export abstract class UnitOfWork<T = Transaction> {
	abstract transaction<Return>(fn: (tx: T) => Promise<Return>): Promise<Return>
}

import { UnitOfWork, UnitOfWorkFactory } from './UnitOfWork'
import { DrizzleClient } from '../../db/client'
import { injectable } from 'tsyringe-neo'

export type DrizzleTransaction = Parameters<Parameters<DrizzleClient['transaction']>[0]>[0]

@injectable()
export class DrizzleUnitOfWork extends UnitOfWork<DrizzleTransaction> {
	constructor(private db: DrizzleClient) {
		super()
	}

	async transaction<Return>(fn: (tx: DrizzleTransaction) => Promise<Return>): Promise<Return> {
		return this.db.transaction(async tx => {
			return fn(tx)
		})
	}
}

@injectable()
export class DrizzleUnitOfWorkFactory extends UnitOfWorkFactory {
	constructor(private db: DrizzleClient) {
		super()
	}

	create(): UnitOfWork<DrizzleTransaction> {
		return new DrizzleUnitOfWork(this.db)
	}
}

export abstract class OutboxDispatcher {
	abstract start(): void
	abstract stop(): Promise<void>
	abstract flush(): Promise<void>
}

import { injectable } from 'tsyringe-neo'
import { DrizzleClient } from '../../db'
import { outbox } from '@bk-dash/contracts/db'
import { InternalMediator } from '../Mediator'
import { OutboxDispatcher } from './OutboxDispatcher'
import { BaseEvent } from '../../types/BaseEvent'
import { BaseError } from '../../types/BaseError'
import type { BaseInfrastructureErrors } from '../../errors/codes'
import { eq, sql, inArray } from 'drizzle-orm'
import { tryCatchAsync } from '../../utils/TryCatch'
import { LoggingService } from '../Logging'

// ─── Configuration ───────────────────────────────────────────────────────────
const BATCH_SIZE = 50
const MAX_ATTEMPTS = 5
const OWNER_CONCURRENCY = 10

// Adaptive polling bounds
const POLL_MIN_MS = 100
const POLL_MAX_MS = 30_000
const POLL_BACKOFF_FACTOR = 1.5

type OutboxRow = typeof outbox.$inferSelect

interface OwnerBatch {
	ownerId: string
	rows: OutboxRow[]
}

interface DispatchResult {
	succeeded: string[]
	failed: { id: string; currentAttempts: number; error: string }[]
	skipped: string[]
}

@injectable()
export class DrizzleOutboxDispatcher extends OutboxDispatcher {
	private timer: ReturnType<typeof setInterval> | null = null
	private isProcessing = false
	private stopping = false
	private pollIntervalMs = POLL_MIN_MS
	private lastProcessedCount = 0

	constructor(
		private db: DrizzleClient,
		private internalMediator: InternalMediator,
		private loggingService: LoggingService,
	) {
		super()
	}

	start(): void {
		this.stopping = false
		console.log(
			`✅ OutboxDispatcher started (adaptive poll: ${POLL_MIN_MS}-${POLL_MAX_MS}ms, batch: ${BATCH_SIZE}, ownerConcurrency: ${OWNER_CONCURRENCY})`,
		)
		this.scheduleNext()
	}

	async stop(): Promise<void> {
		this.stopping = true

		if (this.timer) {
			clearTimeout(this.timer)
			this.timer = null
		}

		// Wait for in-flight processing to finish
		while (this.isProcessing) {
			await new Promise(resolve => setTimeout(resolve, 50))
		}

		console.log('✅ OutboxDispatcher stopped')
	}

	// ─── Scheduling ────────────────────────────────────────────────────────

	private scheduleNext(): void {
		if (this.stopping) return
		if (this.timer) {
			clearTimeout(this.timer)
			this.timer = null
		}
		const interval = Math.min(this.pollIntervalMs, POLL_MAX_MS)
		this.timer = setTimeout(() => this.poll(), interval)
	}

	private adaptPolling(rowsFound: number): void {
		if (rowsFound > 0) {
			this.pollIntervalMs = POLL_MIN_MS
		} else {
			this.pollIntervalMs = Math.min(this.pollIntervalMs * POLL_BACKOFF_FACTOR, POLL_MAX_MS)
		}
	}

	// ─── Main Loop ─────────────────────────────────────────────────────────

	private async poll(): Promise<void> {
		if (this.isProcessing) {
			this.scheduleNext()
			return
		}

		this.isProcessing = true

		try {
			await this.flush()
			this.adaptPolling(this.lastProcessedCount)
		} catch (error) {
			this.loggingService.error({
				content: {
					message: 'OutboxDispatcher poll error',
					error: String(error),
					cause: error instanceof Error && error.cause ? String(error.cause) : undefined,
				},
			})
			this.pollIntervalMs = Math.min(this.pollIntervalMs * POLL_BACKOFF_FACTOR, POLL_MAX_MS)
		} finally {
			this.isProcessing = false
			this.scheduleNext()
		}
	}

	// ─── Three-Phase Processing ────────────────────────────────────────────

	/**
	 * Phase 1: Claim — Short DB transaction using FOR UPDATE SKIP LOCKED.
	 * Marks rows with processedAt so other workers skip them.
	 */
	private async claimBatch(): Promise<OwnerBatch[]> {
		const now = new Date()

		const claimed = await this.db.transaction(async tx => {
			const rows = await tx
				.select()
				.from(outbox)
				.where(sql`${outbox.processedAt} IS NULL AND ${outbox.attempts} < ${MAX_ATTEMPTS}`)
				.orderBy(outbox.ownerId, outbox.createdAt)
				.limit(BATCH_SIZE)
				.for('update', { skipLocked: true })

			if (rows.length === 0) return []

			const ids = rows.map(r => r.id)
			await tx.update(outbox).set({ processedAt: now }).where(inArray(outbox.id, ids))

			return rows
		})

		if (claimed.length === 0) return []

		// Group by ownerId for owner-sequential processing.
		// Null ownerId (events with no actor — e.g. BillingWebhookReceivedEvent)
		// gets a sentinel bucket so it dispatches in parallel with everything else.
		const ownerMap = new Map<string, OutboxRow[]>()
		for (const row of claimed) {
			const key = row.ownerId ?? '__no_owner__'
			const existing = ownerMap.get(key)
			if (existing) {
				existing.push(row)
			} else {
				ownerMap.set(key, [row])
			}
		}

		return Array.from(ownerMap.entries()).map(([ownerId, rows]) => ({ ownerId, rows }))
	}

	/**
	 * Phase 2: Process — Dispatch events OUTSIDE any database transaction.
	 * Sequential within each tenant (preserves ordering), parallel across tenants.
	 * When a tenant event fails, remaining events for that tenant are skipped (not retried with incremented attempts).
	 */
	private async processEvents(ownerBatches: OwnerBatch[]): Promise<DispatchResult> {
		const succeeded: string[] = []
		const failed: DispatchResult['failed'] = []
		const skipped: string[] = []

		const ownerWorker = async (batch: OwnerBatch): Promise<void> => {
			let hasFailed = false

			for (const row of batch.rows) {
				if (hasFailed) {
					// Prior event failed — skip remaining to preserve owner ordering
					skipped.push(row.id)
					continue
				}

				const result = await tryCatchAsync(async () => {
					const event = this.toBaseEvent(row.payload as Record<string, unknown>)
					await this.internalMediator.dispatch(event)
				})

				if (result.success) {
					succeeded.push(row.id)
				} else {
					failed.push({
						id: row.id,
						currentAttempts: row.attempts,
						error: String(result.error),
					})
					hasFailed = true
				}
			}
		}

		// Controlled parallelism: process in chunks of OWNER_CONCURRENCY
		for (let i = 0; i < ownerBatches.length; i += OWNER_CONCURRENCY) {
			const chunk = ownerBatches.slice(i, i + OWNER_CONCURRENCY)
			await Promise.all(chunk.map(ownerWorker))
		}

		return { succeeded, failed, skipped }
	}

	/**
	 * Phase 3: Finalize — Short DB transaction.
	 * Delete succeeded rows, increment attempts on failed, release skipped for retry.
	 */
	private async finalize({ succeeded, failed, skipped }: DispatchResult): Promise<void> {
		await this.db.transaction(async tx => {
			// Delete successfully dispatched rows
			if (succeeded.length > 0) {
				await tx.delete(outbox).where(inArray(outbox.id, succeeded))
			}

			// Failed rows: increment attempts, dead-letter if max reached
			for (const fail of failed) {
				const newAttempts = fail.currentAttempts + 1
				await tx
					.update(outbox)
					.set({
						attempts: newAttempts,
						processedAt: newAttempts >= MAX_ATTEMPTS ? new Date() : null,
					})
					.where(eq(outbox.id, fail.id))

				this.loggingService.error({
					content: {
						message: 'Failed to dispatch outbox event',
						outboxId: fail.id,
						attempts: newAttempts,
						maxReached: newAttempts >= MAX_ATTEMPTS,
						error: fail.error,
					},
				})
			}

			// Skipped rows: release back for next cycle (clear processedAt, don't touch attempts)
			if (skipped.length > 0) {
				await tx.update(outbox).set({ processedAt: null }).where(inArray(outbox.id, skipped))
			}
		})
	}

	/**
	 * Full cycle: claim → process → finalize.
	 * Recurses to drain events produced by handlers.
	 */
	async flush(): Promise<void> {
		const ownerBatches = await this.claimBatch()
		if (ownerBatches.length === 0) {
			this.lastProcessedCount = 0
			return
		}

		this.lastProcessedCount = ownerBatches.reduce((sum, b) => sum + b.rows.length, 0)
		const result = await this.processEvents(ownerBatches)
		await this.finalize(result)

		// Recurse to drain events produced by handlers
		await this.flush()
	}

	/**
	 * Validates that a JSONB payload has the required BaseEvent shape.
	 * The outbox table is only written by BaseEvent.toJSON(), so the shape is guaranteed
	 * to contain name, id, time, and payload fields at runtime.
	 *
	 * Accepted deviation (cc-bp-04): The `as unknown as BaseEvent` cast is unavoidable because
	 * BaseEvent is an abstract class — JSONB deserialization produces plain objects, not class
	 * instances, so structural compatibility cannot be achieved without this assertion.
	 * The type guard above validates the runtime shape before the cast.
	 */
	private toBaseEvent(payload: Record<string, unknown>): BaseEvent {
		if (typeof payload.name !== 'string' || typeof payload.id !== 'string' || typeof payload.time !== 'string') {
			throw new BaseError<BaseInfrastructureErrors>(
				'INVALID_OUTBOX_PAYLOAD',
				'Outbox payload is missing required BaseEvent fields (name, id, time). Outbox rows are only written by BaseEvent.toJSON() — this indicates data corruption or a manual insert bypassing the repository.',
			)
		}
		return payload as unknown as BaseEvent
	}
}

import { DomainEventRepository, type DomainEventConstructor } from './DomainEventRepository'
import { BaseDomainEvent } from '../types/BaseDomainEvent'
import { DrizzleClient } from '../db'
import { events, outbox } from '@bk-dash/contracts/db'
import { and, desc, eq, like, sql } from 'drizzle-orm'
import { injectable } from 'tsyringe-neo'
import { tryCatchAsync } from '../utils/TryCatch'

@injectable()
export class DrizzleDomainEventRepository extends DomainEventRepository {
	constructor(private db: DrizzleClient) {
		super()
	}

	async findById(id: string, transaction?: DrizzleClient): Promise<BaseDomainEvent | undefined> {
		const dbClient = transaction ?? this.db

		const result = await tryCatchAsync(async () => {
			const rows = await dbClient.select().from(events).where(eq(events.id, id)).limit(1)
			return rows[0]
		})

		if (!result.success) throw result.error
		if (!result.data) return undefined

		return this.toDomain(result.data)
	}

	async save(event: BaseDomainEvent, transaction?: DrizzleClient): Promise<BaseDomainEvent> {
		const dbClient = transaction ?? this.db

		await dbClient.insert(events).values(this.toPersistence(event))
		await dbClient.insert(outbox).values(this.toOutboxRow(event))

		return event
	}

	async saveMany(domainEvents: BaseDomainEvent[], transaction?: DrizzleClient): Promise<void> {
		if (domainEvents.length === 0) return

		const dbClient = transaction ?? this.db

		// Two bulk inserts instead of 2N per-row inserts. Drizzle's
		// `.insert().values([...])` batches into a single statement.
		await dbClient.insert(events).values(domainEvents.map(e => this.toPersistence(e)))
		await dbClient.insert(outbox).values(domainEvents.map(e => this.toOutboxRow(e)))
	}

	async saveIfNotExists(event: BaseDomainEvent, transaction?: DrizzleClient): Promise<boolean> {
		const dbClient = transaction ?? this.db

		// ON CONFLICT DO NOTHING catches any unique constraint — including
		// partial indexes like events_billing_webhook_received_entity_unq.
		// RETURNING is empty when the row was rejected.
		const inserted = await dbClient.insert(events).values(this.toPersistence(event)).onConflictDoNothing().returning({ id: events.id })

		if (inserted.length === 0) return false

		// If the events insert succeeded, the outbox row mirrors it. If we
		// skipped (duplicate), we MUST skip the outbox too — otherwise the
		// dispatcher delivers a duplicate event downstream.
		await dbClient.insert(outbox).values(this.toOutboxRow(event))
		return true
	}

	async delete(id: string, transaction?: DrizzleClient): Promise<void> {
		const dbClient = transaction ?? this.db

		const result = await tryCatchAsync(async () => {
			await dbClient.delete(events).where(eq(events.id, id))
		})

		if (!result.success) throw result.error
	}

	async findByOwnerIdAndNameLike(
		ownerId: string,
		nameLike: string,
		opts: { limit: number; offset: number },
		transaction?: DrizzleClient,
	): Promise<{ items: BaseDomainEvent[]; total: number }> {
		const dbClient = transaction ?? this.db

		const filters = and(eq(events.ownerId, ownerId), like(events.name, nameLike))

		const result = await tryCatchAsync(async () => {
			const [countRow] = await dbClient.select({ n: sql<number>`count(*)::int` }).from(events).where(filters)

			const rows = await dbClient
				.select()
				.from(events)
				.where(filters)
				.orderBy(desc(events.occurredAt))
				.limit(opts.limit)
				.offset(Math.max(0, opts.offset))

			return {
				items: rows.map(r => this.toDomain(r)),
				total: Number(countRow?.n ?? 0),
			}
		})

		if (!result.success) throw result.error
		return result.data
	}

	async findByType<E extends BaseDomainEvent>(eventClass: DomainEventConstructor<E>, transaction?: DrizzleClient): Promise<E[]> {
		const dbClient = transaction ?? this.db

		const result = await tryCatchAsync(async () => {
			const rows = await dbClient.select().from(events).where(eq(events.name, eventClass.name)).orderBy(events.occurredAt)
			// Rehydrate each row into a real event instance via its concrete class,
			// so the caller gets `E` with a typed payload (no row/JSONB casts upstream).
			return rows.map(r => new eventClass({ entityId: r.entityId ?? undefined, ownerId: r.ownerId ?? undefined, payload: r.payload }))
		})

		if (!result.success) throw result.error
		return result.data
	}

	/**
	 * Accepted deviation (cc-bp-04): BaseDomainEvent is an abstract class — it cannot be
	 * instantiated from a plain DB row. The Drizzle row is structurally compatible at runtime
	 * (same fields: id, name, entityId, ownerId, payload, time) but TypeScript cannot verify
	 * this because the target is an abstract class with a constructor. A full fix requires a
	 * concrete DomainEvent factory or registry, which is out of scope for an append-only event log.
	 */
	private toDomain(row: typeof events.$inferSelect): BaseDomainEvent {
		return row as unknown as BaseDomainEvent
	}

	private toPersistence(event: BaseDomainEvent): typeof events.$inferInsert {
		return {
			id: event.id,
			name: event.name,
			entityId: event.entityId,
			ownerId: event.ownerId,
			payload: JSON.parse(JSON.stringify(event.payload)) as Record<string, unknown>,
			source: 'api',
			occurredAt: new Date(event.time),
		}
	}

	private toOutboxRow(event: BaseDomainEvent): typeof outbox.$inferInsert {
		return {
			id: event.id,
			name: event.name,
			entityId: event.entityId,
			ownerId: event.ownerId,
			payload: event.toJSON() as unknown as Record<string, unknown>,
			source: 'api',
		}
	}
}

import { pgSchema, uuid, text, timestamp, integer, jsonb, index, primaryKey, uniqueIndex } from 'drizzle-orm/pg-core'
import { sql } from 'drizzle-orm'

export const sharedSchema = pgSchema('shared')

export const events = sharedSchema.table(
	'events',
	{
		id: uuid('id').primaryKey().defaultRandom(),
		name: text('name').notNull(),
		// Nullable — some events (BillingWebhookReceivedEvent etc.) carry a
		// computed entityId for indexing; others don't have a meaningful one.
		entityId: uuid('entity_id'),
		// Nullable — pure "something happened" events may have no actor owner.
		ownerId: text('owner_id'),
		payload: jsonb('payload').notNull(),
		source: text('source').notNull(),
		occurredAt: timestamp('occurred_at', { withTimezone: true }).notNull().defaultNow(),
	},
	t => ({
		entityIdx: index('events_entity_idx').on(t.entityId, t.occurredAt),
		nameIdx: index('events_name_idx').on(t.name, t.occurredAt),
		// Webhook-arrival idempotency: at most one billing.webhook.received row per
		// entity_id (= deterministic hash of platform + externalEventId). The
		// HandleBillingWebhook use case catches the unique-violation as the
		// idempotent-ack signal. Partial index keeps the constraint scoped to the
		// one event name that needs it; other events (which legitimately repeat
		// per entity_id, e.g. SubscriptionPaid every billing cycle) are unaffected.
		// Generalizable: any "received from external system" event with a dedupable
		// external id can add a sibling partial index here.
		billingWebhookReceivedUnq: uniqueIndex('events_billing_webhook_received_entity_unq')
			.on(t.entityId)
			.where(sql`name = 'billing.webhook.received'`),
	}),
)

export const outbox = sharedSchema.table(
	'outbox',
	{
		id: uuid('id').primaryKey().defaultRandom(),
		name: text('name').notNull(),
		entityId: uuid('entity_id'),
		ownerId: text('owner_id'),
		payload: jsonb('payload').notNull(),
		source: text('source').notNull(),
		processedAt: timestamp('processed_at', { withTimezone: true }),
		attempts: integer('attempts').notNull().default(0),
		lastError: text('last_error'),
		createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
	},
	t => ({
		unprocessedIdx: index('outbox_unprocessed_idx').on(t.source, t.processedAt, t.createdAt),
	}),
)

export const idempotencyKeys = sharedSchema.table(
	'idempotency_keys',
	{
		key: text('key').notNull(),
		scope: text('scope').notNull(),
		responseBody: jsonb('response_body'),
		responseStatus: integer('response_status'),
		expiresAt: timestamp('expires_at', { withTimezone: true }).notNull(),
		createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
	},
	t => ({
		pk: primaryKey({ columns: [t.key, t.scope] }),
		expiresIdx: index('idempotency_expires_idx').on(t.expiresAt),
	}),
)

import type { Handler } from '../../types/Handler'
import { tryCatch, tryCatchAsync } from '../../utils/TryCatch'
import { BaseEvent } from '../../types/BaseEvent'
import { DependencyContainer } from 'tsyringe-neo'

export type EventCallback = (event: BaseEvent) => void | Promise<void>
export type Unsubscribe = () => void

/**
 * Resolve every event name a Handler subscribes to. EventHandlers (SPEC-12)
 * expose `events: readonly string[]` for both single-event and multi-event
 * forms; non-event Handlers fall back to `handler.name`.
 */
export function handlerEventNames(handler: Handler): readonly string[] {
	const events = (handler as Handler & { events?: readonly string[] }).events
	if (Array.isArray(events) && events.length > 0) {
		return events
	}
	return [handler.name]
}

export abstract class Mediator {
	abstract register(handler: Handler): void
	abstract execute<T extends Handler>(handler: T['name'], input: T['input']): Promise<T['output']>
	abstract publish(event: BaseEvent): Promise<void>
	abstract dispatch(event: BaseEvent): Promise<void>
	abstract removeAllListeners(): void
	abstract registerCallback(callback: EventCallback, eventName?: string): Unsubscribe

	// Lifecycle hooks — default no-op. Concrete mediators with networked transports
	// (Redis, Kafka, ...) override to open/close connections.
	async start(): Promise<void> {}
	async stop(): Promise<void> {}

	static async register(
		container: DependencyContainer,
		mediator: Mediator,
		handlers: Record<string, new (...args: any[]) => Handler>,
	): Promise<number> {
		const handlerInstances: Handler[] = []
		let successCount = 0

		for (const [handlerName, HandlerClass] of Object.entries(handlers)) {
			if (typeof HandlerClass === 'function' && handlerName !== 'default') {
				const result = tryCatch(() => {
					const handlerInstance = container.resolve(HandlerClass).bindContainer(container)
					handlerInstances.push(handlerInstance)
					successCount++
				})
				if (!result.success) {
					console.warn(`Failed to resolve Handler ${handlerName}:`, result.error)
				}
			}
		}

		for (const handler of handlerInstances) {
			const result = await tryCatchAsync(async () => {
				await mediator.register(handler)
			})
			if (!result.success) {
				console.warn(`Failed to register Handler:`, result.error)
				successCount--
			}
		}

		console.log(`✅ Registered ${successCount} Handlers`)
		return successCount
	}
}

export abstract class InternalMediator extends Mediator {}

export abstract class ExternalMediator extends Mediator {}

import { BaseInfrastructureErrors } from '../../errors/codes'
import { BaseEvent } from '../../types/BaseEvent'
import { BaseError } from '../../types/BaseError'
import { Handler } from '../../types/Handler'
import { tryCatchAsync } from '../../utils/TryCatch'
import EventEmitter2 from 'eventemitter2'
import { EventCallback, Mediator, Unsubscribe, handlerEventNames } from '.'
import { injectable } from 'tsyringe-neo'

@injectable()
export class EventEmitter2Mediator extends Mediator {
	private readonly eventEmitter = new EventEmitter2({
		wildcard: true,
	})

	private registeredHandlers = new Set<string>()
	private handlerMap = new Map<string, Handler[]>()

	async register(handler: Handler): Promise<void> {
		const names = handlerEventNames(handler)
		for (const name of names) {
			// If already registered for this event name, remove the old EventEmitter2
			// listener and handler map entry before re-adding so we never accumulate
			// stale listeners.
			if (this.registeredHandlers.has(name)) {
				console.warn(`Handler ${name} already registered, replacing existing registration`)
				this.eventEmitter.removeAllListeners(name)
				this.handlerMap.delete(name)
				this.registeredHandlers.delete(name)
			}

			this.registeredHandlers.add(name)

			// Store handler reference for dispatch() (synchronous, error-propagating)
			if (!this.handlerMap.has(name)) {
				this.handlerMap.set(name, [])
			}
			this.handlerMap.get(name)!.push(handler)

			// Register for publish() (fire-and-forget via EventEmitter2)
			this.eventEmitter.on(name, async (event: BaseEvent) => {
				void tryCatchAsync(async () => handler.execute(event))
			})
		}
	}

	async publish(event: BaseEvent): Promise<void> {
		this.eventEmitter.emit(event.name, event)
	}

	async dispatch(event: BaseEvent): Promise<void> {
		const handlers = this.handlerMap.get(event.name)

		if (!handlers || handlers.length === 0) {
			return
		}

		for (const handler of handlers) {
			await handler.execute(event)
		}
	}

	async execute<T extends Handler>(_handler: T['name'], _input: T['input']): Promise<T['output']> {
		throw new BaseError<BaseInfrastructureErrors>('NOT_IMPLEMENTED')
	}

	removeAllListeners(): void {
		this.eventEmitter.removeAllListeners()
		this.registeredHandlers.clear()
		this.handlerMap.clear()
		console.log('✅ Removed all event listeners')
	}

	getHandlerCount(): number {
		return this.registeredHandlers.size
	}

	registerCallback(callback: EventCallback, eventName?: string): Unsubscribe {
		const event = eventName ?? '**'
		this.eventEmitter.on(event, callback)
		return () => {
			this.eventEmitter.off(event, callback)
		}
	}
}

import IORedis from 'ioredis'
import { hostname } from 'node:os'
import { BaseEvent } from '../../types/BaseEvent'
import { Handler } from '../../types/Handler'
import { BaseInfrastructureErrors } from '../../errors/codes'
import { BaseError } from '../../types/BaseError'
import { tryCatchAsync } from '../../utils/TryCatch'
import { Config } from '../../utils/Config'
import { EventCallback, ExternalMediator, Unsubscribe, handlerEventNames } from './Mediator'
import { injectable } from 'tsyringe-neo'

const STREAM_PREFIX = 'events:'
const DEAD_SUFFIX = ':dead'
const MAX_STREAM_LEN = 10_000
const READ_COUNT = 32
const BLOCK_MS = 5_000
const MAX_DELIVERIES = 5

type XReadGroupResult = null | [string, [string, string[]][]][]

@injectable()
export class RedisExternalMediator extends ExternalMediator {
	private producer!: IORedis
	private consumer!: IORedis
	private groupId!: string
	private consumerName!: string
	private handlerMap = new Map<string, Handler[]>()
	private callbacks = new Set<EventCallback>()
	private namedCallbacks = new Map<string, Set<EventCallback>>()
	private consuming = false
	private stopped = false
	private readLoop: Promise<void> | null = null

	override async start(): Promise<void> {
		await this.connect()
		await this.startConsuming()
	}

	override async stop(): Promise<void> {
		await this.disconnect()
	}

	private async connect(): Promise<void> {
		// Disconnect stale connections from bun --hot reload (same singleton, new start)
		this.consumer?.disconnect()
		this.producer?.disconnect()
		this.consuming = false
		this.stopped = false
		this.readLoop = null
		this.handlerMap.clear()

		const url = Config.env.REDIS_URL
		this.groupId = Config.env.API_EVENT_GROUP_ID
		this.consumerName = `${this.groupId}-${hostname()}-${process.pid}`

		this.producer = new IORedis(url, { maxRetriesPerRequest: null })
		this.consumer = new IORedis(url, { maxRetriesPerRequest: null })

		await Promise.all([this.producer.ping(), this.consumer.ping()])
		console.log('✅ Redis mediator connected')
	}

	async register(handler: Handler): Promise<void> {
		for (const name of handlerEventNames(handler)) {
			const existing = this.handlerMap.get(name)
			if (existing) {
				existing.push(handler)
				continue
			}
			this.handlerMap.set(name, [handler])
		}
	}

	private async startConsuming(): Promise<void> {
		if (this.consuming) return

		const streams = Array.from(this.handlerMap.keys(), streamKey)
		if (streams.length === 0) {
			console.log('No external handler streams to subscribe to, skipping Redis consumer')
			return
		}

		for (const stream of streams) {
			try {
				await this.consumer.xgroup('CREATE', stream, this.groupId, '$', 'MKSTREAM')
			} catch (error) {
				const message = error instanceof Error ? error.message : String(error)
				if (!message.includes('BUSYGROUP')) {
					console.warn(`Failed to create consumer group for ${stream}:`, message)
				}
			}
		}

		this.consuming = true
		this.readLoop = this.runReadLoop(streams).catch(error => {
			console.error('Redis read loop crashed:', error)
		})

		console.log(`✅ Redis consumer running on ${streams.length} streams: ${streams.map(stripPrefix).join(', ')}`)
	}

	async publish(event: BaseEvent): Promise<void> {
		const payload = JSON.stringify(event.toJSON())
		await this.producer.xadd(streamKey(event.name), 'MAXLEN', '~', MAX_STREAM_LEN, '*', 'data', payload)
		this.notifyCallbacks(event.name, event)
	}

	async dispatch(event: BaseEvent): Promise<void> {
		// Fire-and-forget to match in-process dispatch semantics of the Kafka implementation.
		const handlers = this.handlerMap.get(event.name)
		if (!handlers) return

		for (const handler of handlers) {
			void tryCatchAsync(async () => handler.execute(event)).then(result => {
				if (!result.success) {
					console.error(`[Redis] Handler ${handler.name} failed for event ${event.name}:`, result.error)
				}
			})
		}
	}

	async execute<T extends Handler>(_handler: T['name'], _input: T['input']): Promise<T['output']> {
		throw new BaseError<BaseInfrastructureErrors>('NOT_IMPLEMENTED')
	}

	removeAllListeners(): void {
		this.handlerMap.clear()
		this.callbacks.clear()
		this.namedCallbacks.clear()
	}

	registerCallback(callback: EventCallback, eventName?: string): Unsubscribe {
		if (eventName) {
			let set = this.namedCallbacks.get(eventName)
			if (!set) {
				set = new Set()
				this.namedCallbacks.set(eventName, set)
			}
			set.add(callback)
			return () => set!.delete(callback)
		}

		this.callbacks.add(callback)
		return () => this.callbacks.delete(callback)
	}

	private async disconnect(): Promise<void> {
		this.stopped = true
		await this.readLoop?.catch(() => {})
		this.readLoop = null
		this.consumer?.disconnect()
		this.producer?.disconnect()
		console.log('✅ Redis mediator disconnected')
	}

	private async runReadLoop(streams: string[]): Promise<void> {
		// First drain any pending entries from a previous run, then switch to live mode.
		let draining = true

		while (!this.stopped) {
			const ids = streams.map(() => (draining ? '0' : '>'))
			const result = await tryCatchAsync(() =>
				(this.consumer.xreadgroup as any)(
					'GROUP',
					this.groupId,
					this.consumerName,
					'COUNT',
					READ_COUNT,
					'BLOCK',
					BLOCK_MS,
					'STREAMS',
					...streams,
					...ids,
				),
			)
			if (!result.success) {
				if (this.stopped) return
				console.error('Redis XREADGROUP failed:', result.error)
				await sleep(1000)
				continue
			}

			const entries = result.data as XReadGroupResult
			let sawAny = false
			for (const [stream, messages] of entries ?? []) {
				if (messages.length === 0) continue
				sawAny = true
				for (const [id, fields] of messages) {
					await this.processEntry(stream, id, fields)
				}
			}

			if (draining && !sawAny) draining = false
		}
	}

	private async processEntry(stream: string, id: string, fields: string[]): Promise<void> {
		const eventName = stripPrefix(stream)
		const data = getField(fields, 'data')
		if (!data) {
			await this.ack(stream, id)
			return
		}

		let parsed: unknown
		try {
			parsed = JSON.parse(data)
		} catch (error) {
			console.error(`Failed to parse Redis entry on ${stream} (${id}):`, error)
			await this.moveToDeadLetter(stream, id, data, 'parse_error')
			return
		}

		const handlers = this.handlerMap.get(eventName) ?? []
		for (const handler of handlers) {
			const result = await tryCatchAsync(() => handler.execute(parsed))
			if (!result.success) {
				console.error(`Handler ${handler.name} failed on ${id}:`, result.error)
				const deliveries = await this.getDeliveryCount(stream, id)
				if (deliveries >= MAX_DELIVERIES) {
					await this.moveToDeadLetter(stream, id, data, String(result.error))
				}
				// Otherwise leave unacked so the PEL redelivers on next draining pass.
				return
			}
		}

		if (isBaseEvent(parsed)) this.notifyCallbacks(eventName, parsed)
		await this.ack(stream, id)
	}

	private async ack(stream: string, id: string): Promise<void> {
		const result = await tryCatchAsync(() => this.consumer.xack(stream, this.groupId, id))
		if (!result.success) {
			console.error(`Failed to XACK ${stream}/${id}:`, result.error)
		}
	}

	private async getDeliveryCount(stream: string, id: string): Promise<number> {
		const result = await tryCatchAsync(() => (this.consumer.xpending as any)(stream, this.groupId, 'IDLE', 0, id, id, 1))
		if (!result.success || !Array.isArray(result.data) || result.data.length === 0) return 0
		// XPENDING entry shape: [id, consumer, idleMs, deliveryCount]
		const count = Number((result.data[0] as unknown[])[3] ?? 0)
		return Number.isFinite(count) ? count : 0
	}

	private async moveToDeadLetter(stream: string, id: string, data: string, reason: string): Promise<void> {
		const deadStream = stream + DEAD_SUFFIX
		const result = await tryCatchAsync(() =>
			this.producer.xadd(deadStream, 'MAXLEN', '~', MAX_STREAM_LEN, '*', 'data', data, 'reason', reason, 'originalId', id),
		)
		if (!result.success) {
			console.error(`Failed to push ${id} to dead-letter stream ${deadStream}:`, result.error)
			return
		}
		await this.ack(stream, id)
		console.warn(`Moved ${id} from ${stream} to ${deadStream} (reason: ${reason})`)
	}

	private notifyCallbacks(eventName: string, event: BaseEvent): void {
		for (const cb of this.callbacks) cb(event)
		const named = this.namedCallbacks.get(eventName)
		if (named) for (const cb of named) cb(event)
	}
}

function streamKey(eventName: string): string {
	return STREAM_PREFIX + eventName
}

function stripPrefix(stream: string): string {
	return stream.startsWith(STREAM_PREFIX) ? stream.slice(STREAM_PREFIX.length) : stream
}

function getField(fields: string[], key: string): string | undefined {
	for (let i = 0; i < fields.length; i += 2) {
		if (fields[i] === key) return fields[i + 1]
	}
	return undefined
}

function isBaseEvent(value: unknown): value is BaseEvent {
	return typeof value === 'object' && value !== null && 'name' in value && 'id' in value && 'payload' in value
}

function sleep(ms: number): Promise<void> {
	return new Promise(resolve => setTimeout(resolve, ms))
}

import type { Transaction } from '../services/UnitOfWork'

/**
 * Base class for read-side handlers — one Projector per Projection.
 * Subscribes to a union of events; implementation switches on event.name.
 * Async via outbox by default; can be invoked inline by a use case for
 * read-after-write consistency.
 *
 * ref: .claude/skills/projector/SKILL.md
 */
export abstract class Projector<E = any> {
	/** Event names this projector listens to. BoundedContext.create registers each on InternalMediator. */
	abstract readonly events: readonly string[]

	/** Implementations switch on event.name. */
	abstract handle(event: E, tx?: Transaction): Promise<void>
}

import { z, type ZodType } from 'zod'
import { type BaseEvent } from './BaseEvent'
import { Handler } from './Handler'
import type { Transaction } from '../services/UnitOfWork'

interface EventClass<S extends ZodType = ZodType> {
	name: string
	schema: S
	new (...args: any[]): BaseEvent
}

type EventClassOrArray = EventClass | readonly EventClass[]

type EventClassesOf<E extends EventClassOrArray> = E extends readonly EventClass[] ? E[number] : E

type SchemaOf<E extends EventClassOrArray> = EventClassesOf<E>['schema']

/**
 * Per-event handler. SPEC-12 generalised the shape to accept either a single
 * event class or `readonly [EventClass, EventClass, ...]` for multi-event
 * subscriptions. Single-event handlers behave as before; multi-event handlers
 * receive a union-typed event inside `handle()` and discriminate via
 * `event.name` switch.
 *
 * Sub-handler discipline (SPEC-12 §"Sub-handler discipline"): sub-handlers
 * `extends EventHandler` like any other handler but are NOT re-exported from
 * `handlers/internal.ts` / `handlers/external.ts` — the barrel is the
 * registration gate, so unexported handlers stay invisible to the mediator.
 */
export abstract class EventHandler<E extends EventClassOrArray> extends Handler<SchemaOf<E>, z.ZodVoid> {
	abstract readonly event: E

	/** Names of every event this handler subscribes to. Mediator iterates this when registering. */
	get events(): readonly string[] {
		const e = this.event as EventClassOrArray
		return Array.isArray(e) ? (e as readonly EventClass[]).map(c => c.name) : [(e as EventClass).name]
	}

	/**
	 * @deprecated Use `events`. For single-event handlers returns `events[0]`;
	 * throws for multi-event handlers because the answer is ambiguous.
	 */
	get name(): string {
		const ev = this.events
		if (ev.length > 1) {
			throw new Error('EventHandler.name is ambiguous for multi-event handlers; use .events')
		}
		return ev[0]!
	}

	get inputSchema(): SchemaOf<E> {
		const e = this.event as EventClassOrArray
		if (Array.isArray(e)) {
			// For multi-event handlers, return the first class's schema as a placeholder.
			// Runtime validation is per-event inside handle(); the framework's input
			// inference here is only consulted for the BaseEvent envelope shape.
			return (e[0] as EventClass).schema as SchemaOf<E>
		}
		return (e as EventClass).schema as SchemaOf<E>
	}

	readonly outputSchema = z.void()

	override async execute(input: any): Promise<void> {
		const e = this.event as EventClassOrArray
		if (Array.isArray(e)) {
			// Multi-event: trust the caller to have constructed the right class.
			await this.handle(input as this['input'])
			return
		}
		const Cls = e as EventClass
		const event = input instanceof Cls ? input : new Cls(input)
		await this.handle(event as this['input'])
	}

	// Narrow the abstract `handle` return type from
	// `Promise<this['output']>` to `Promise<void>`. With outputSchema
	// = z.void() the inferred this['output'] already resolves to
	// void, but TypeScript can't see through the generic indirection
	// from inside subclass bodies — so without this override every
	// subclass needed `return undefined as never`. Concrete subclasses
	// now `return` (or omit it) cleanly.
	protected abstract override handle(input: this['input'], tx?: Transaction): Promise<void>
}

import { BaseInterfaceErrors, type BaseInfrastructureErrors } from '../errors/codes'
import { tryCatchAsync } from '../utils/TryCatch'
import { BaseError } from './BaseError'
import { UnitOfWorkFactory, type Transaction } from '../services/UnitOfWork/UnitOfWork'
import { z, type ZodType, type ZodIssue } from 'zod'
import type { DependencyContainer } from 'tsyringe-neo'

// Type-only imports to avoid circular dependencies
import { DomainEventRepository } from '../repositories/DomainEventRepository'
import { InternalMediator, type Mediator } from '../services/Mediator/Mediator'

export abstract class Handler<
	InputSchema extends ZodType = ZodType,
	OutputSchema extends ZodType = ZodType,
	// Default to the persistence-agnostic Transaction, NOT DrizzleClient: withTransaction
	// yields this to handlers/use cases, which pass it straight to repos. Only the Drizzle
	// repo impls narrow it to DrizzleClient. Keeps infra out of the write-side flow.
	Tx extends Transaction = Transaction,
> {
	private _container?: DependencyContainer

	abstract readonly name: string
	abstract readonly inputSchema: InputSchema
	abstract readonly outputSchema: OutputSchema
	readonly concurrency?: number

	readonly input!: z.output<(typeof this)['inputSchema']>
	readonly output!: z.output<(typeof this)['outputSchema']>

	bindContainer(container: DependencyContainer): this {
		this._container = container
		this.bindChildHandlers(this, container, new WeakSet())
		return this
	}

	private bindChildHandlers(target: object, container: DependencyContainer, visited: WeakSet<object>): void {
		if (visited.has(target)) return
		visited.add(target)

		for (const value of Object.values(target)) {
			this.visitForBinding(value, container, visited)
		}
	}

	private visitForBinding(value: unknown, container: DependencyContainer, visited: WeakSet<object>): void {
		if (!value || typeof value !== 'object') return
		if (value instanceof Handler) {
			if (!value._container) value.bindContainer(container)
			return
		}
		if (Array.isArray(value)) {
			for (const item of value) this.visitForBinding(item, container, visited)
			return
		}
		if (Object.getPrototypeOf(value) !== Object.prototype) {
			this.bindChildHandlers(value, container, visited)
		}
	}

	protected get di(): DependencyContainer {
		if (!this._container) {
			throw new BaseError<BaseInfrastructureErrors>(
				'HANDLER_NOT_BOUND',
				`${this.constructor.name} was resolved without a bound DI container. Resolve the handler via Handler.bindContainer(container) or through the DI-registered handler pipeline instead of constructing it directly.`,
			)
		}

		return this._container
	}

	// Core infrastructure — lazily resolved from the handler DI container
	protected get unitOfWorkFactory(): UnitOfWorkFactory {
		return this.di.resolve(UnitOfWorkFactory as any)
	}

	protected get domainEventRepository(): DomainEventRepository {
		return this.di.resolve(DomainEventRepository as any) as unknown as DomainEventRepository
	}

	protected get internalMediator(): Mediator {
		return this.di.resolve(InternalMediator as any) as unknown as Mediator
	}

	// `| void` lets handlers whose outputSchema resolves to z.void()
	// (e.g. RegisterFcmToken, UpdateProfile, every EventHandler
	// subclass …) return bare without a cast. TypeScript can't see
	// through the generic indirection to narrow `this['output']` to
	// `void` when outputSchema is z.void(); the union covers that
	// gap without affecting handlers that return a real shape (their
	// compiler-validated `return { … }` still satisfies
	// `this['output']`).
	protected abstract handle(input: this['input'], tx?: Tx): Promise<this['output'] | undefined>

	async execute(input: this['input'], tx?: Tx): Promise<this['output']> {
		const result = await tryCatchAsync(async () => {
			const decodedInput = this.validatedRequest(input)
			return await this.handle(decodedInput, tx)
		})
		if (!result.success) {
			throw result.error
		}
		// handle() returns `this['output'] | void`; cast back to the
		// narrower signature execute() promises. For void-outputting
		// handlers, result.data is undefined which is a valid
		// `void` instance of `this['output']`.
		return result.data as this['output']
	}

	protected async withTransaction<T>(tx: Tx | undefined, fn: (tx: Tx) => Promise<T>): Promise<T> {
		if (tx) return fn(tx)
		const uow = this.unitOfWorkFactory.create()
		return uow.transaction(async newTx => fn(newTx as Tx))
	}

	protected validatedRequest(input: unknown): this['input'] {
		const result = this.inputSchema.safeParse(input)
		if (!result.success) {
			const validationErrorString = this.getValidationErrorString(result.error.issues)
			throw new BaseError<BaseInterfaceErrors>('VALIDATION_ERROR', validationErrorString)
		}
		return result.data
	}

	protected getValidationErrorString(issues: ZodIssue[]): string {
		return issues.map(issue => this.getZodIssueMessage(issue)).join('; ')
	}

	protected getZodIssueMessage(issue: ZodIssue): string {
		const path = issue.path.join('.')
		return `${issue.message} at ${path || 'root'}`
	}
}

import { injectable } from 'tsyringe-neo'
import { BaseError, EventHandler, type Transaction } from '@bk-dash/core-typescript'
import {
	ExternalSubscriptionUpdatedEvent,
	SubscriptionCancelledEvent,
	SubscriptionCreatedEvent,
	SubscriptionOverdueEvent,
	SubscriptionPaidEvent,
	SubscriptionRenewedEvent,
} from '../events'
import { Subscription } from '../entities/Subscription'
import { SubscriptionRepository } from '../repositories/SubscriptionRepository'
import { SubscriptionTransition } from '../enums'
import type { InterfaceErrors } from '../errors'

/**
 * Internal handler for ExternalSubscriptionUpdatedEvent — the single place the
 * webhook flow turns "a provider reported a change" into a real subscription
 * state transition.
 *
 * For each `transition` discriminant it loads (or creates) the Subscription
 * aggregate, calls the imperative domain method, and persists the aggregate +
 * the corresponding domain event in ONE transaction. The domain event is only
 * saved when the transition actually happened — so a cancellation for a row
 * that doesn't exist emits nothing, instead of publishing a SubscriptionCancelled
 * fact that never occurred.
 *
 * The saved domain events ride the outbox to their side-effect handlers (e.g.
 * the SubscriptionQuotaUpdated publishers) — those handlers do effects only,
 * never persistence.
 *
 * Missing-row on a non-created transition is a no-op (defensive against
 * out-of-order outbox delivery — the Created event hasn't landed yet; the
 * dispatcher retries).
 */
@injectable()
export class ExternalSubscriptionUpdatedHandler extends EventHandler<typeof ExternalSubscriptionUpdatedEvent> {
	readonly event = ExternalSubscriptionUpdatedEvent

	constructor(private readonly subscriptions: SubscriptionRepository) {
		super()
	}

	protected async handle(event: this['input'], tx?: Transaction): Promise<void> {
		await this.withTransaction(tx, async tx => {
			const { transition } = event.payload
			switch (transition) {
				case SubscriptionTransition.CREATED:
					return this.applyCreated(event, tx)
				case SubscriptionTransition.PAID:
					return this.applyPaid(event, tx)
				case SubscriptionTransition.RENEWED:
					return this.applyRenewed(event, tx)
				case SubscriptionTransition.CANCELLED:
					return this.applyCancelled(event, tx)
				case SubscriptionTransition.OVERDUE:
					return this.applyOverdue(event, tx)
				default: {
					const _exhaustive: never = transition
					return _exhaustive
				}
			}
		})
	}

	/** First charge → materialise the aggregate + emit SubscriptionCreated. */
	private async applyCreated(event: this['input'], tx: Transaction): Promise<void> {
		const { externalId, platform, tier, userId, period } = event.payload
		// Created carries userId + period (mapper guarantees both); a Created
		// without them is a malformed intermediate event — fail fast.
		if (!userId || !period) {
			throw new BaseError<InterfaceErrors>('BILLING_WEBHOOK_PAYLOAD_INVALID')
		}

		const existing = await this.subscriptions.findByPlatformAndExternalId(platform, externalId, tx)
		if (existing) return

		const subscription = Subscription.create({
			userId,
			platform,
			externalSubscriptionId: externalId,
			tier,
			period,
		})

		await this.subscriptions.save(subscription, tx)
		await this.domainEventRepository.save(
			new SubscriptionCreatedEvent({
				entityId: subscription.id.value,
				ownerId: userId,
				payload: { externalId, platform, tier, userId, period },
			}),
			tx,
		)
	}

	/** Recurring charge on a never-paid subscription. */
	private async applyPaid(event: this['input'], tx: Transaction): Promise<void> {
		const { externalId, platform, tier } = event.payload
		const subscription = await this.subscriptions.findByPlatformAndExternalId(platform, externalId, tx)
		if (!subscription) return

		subscription.markPaid(new Date())
		await this.subscriptions.save(subscription, tx)
		await this.domainEventRepository.save(
			new SubscriptionPaidEvent({
