import { BasePrimitiveValueObject } from './BasePrimitiveValueObject'
import type { BaseDomainErrors } from '../errors/codes'
import { createHash } from 'node:crypto'
import { uuidv7 } from 'uuidv7'
import z from 'zod'

export const IdSchema = z.string().refine(v => v.length > 0, { error: 'INVALID_ID' as BaseDomainErrors })

// Locked UUIDv5 namespace — byte-for-byte identical to `packages/api/go/core/objects/id.go`.
// Changing this orphans every previously-ingested deterministic id. Not exported.
const BK_DASH_NAMESPACE = 'f63cfbe6-7d8e-4d1d-9c5d-9d8a8b1b0c5e' as const

export class Id extends BasePrimitiveValueObject<typeof IdSchema> {
	static override schema = IdSchema

	constructor(value?: string) {
		super(value ?? Id.value())
	}

	/**
	 * Fresh primitive id string (UUIDv7). Use when an external library
	 * needs a raw id generator and we don't want to leak uuidv7 imports
	 * across the codebase.
	 */
	static value(): string {
		return uuidv7()
	}

	/**
	 * Deterministic UUIDv5 from a tuple of strings, using the locked
	 * `BK_DASH_NAMESPACE`. Same algorithm + namespace as Go's
	 * `objects.IDFromSeed(...)` — identical inputs produce identical UUIDs
	 * across languages.
	 *
	 * Implementation: RFC 4122 UUIDv5 = SHA-1(namespace_bytes || name_bytes)
	 * with version + variant bits set per spec. Inlined to avoid a `uuid`
	 * package dependency.
	 */
	static fromSeed(...parts: string[]): Id {
		if (parts.length === 0) throw new Error('Id.fromSeed requires at least one part')
		const name = parts.join(':')

		const namespaceBytes = Buffer.from(BK_DASH_NAMESPACE.replace(/-/g, ''), 'hex')
		const hash = createHash('sha1').update(namespaceBytes).update(name, 'utf8').digest()

		// Set UUIDv5 version (0x50 in byte 6) and RFC 4122 variant (0x80 in byte 8).
		hash[6] = (hash[6]! & 0x0f) | 0x50
		hash[8] = (hash[8]! & 0x3f) | 0x80

		const hex = hash.subarray(0, 16).toString('hex')
		const uuid = `${hex.slice(0, 8)}-${hex.slice(8, 12)}-${hex.slice(12, 16)}-` + `${hex.slice(16, 20)}-${hex.slice(20, 32)}`
		return new Id(uuid)
	}

	equals(other: Id): boolean {
		return this.value === other.value
	}

	override toString(): string {
		return this.value
	}
}

// Generic command-name type — apps narrow this in their own subclasses.
type UseCases = string
import { BaseError } from '../../types/BaseError'
import { Handler } from '../../types/Handler'
import { Config } from '../../utils/Config'
import { JobsOptions, Queue, Worker, type ConnectionOptions, type Job, type WorkerOptions } from 'bullmq'
import { CommandQueue } from './CommandQueue'
import { BaseInfrastructureErrors } from '../../errors/codes'
import { injectable } from 'tsyringe-neo'
import { trace, context, SpanStatusCode } from '@opentelemetry/api'
import { describeValue } from '../../utils/Tracing'
import IORedis from 'ioredis'

@injectable()
export class BullMQ extends CommandQueue {
	private readonly connection: ConnectionOptions
	private readonly sharedConnection: IORedis

	constructor() {
		super()
		const url = new URL(Config.env.REDIS_URL)
		this.connection = {
			host: url.hostname,
			port: Number(url.port) || 6379,
			password: url.password || undefined,
			username: url.username || undefined,
		}
		this.sharedConnection = new IORedis({
			host: url.hostname,
			port: Number(url.port) || 6379,
			password: url.password || undefined,
			username: url.username || undefined,
			maxRetriesPerRequest: 5,
		})
	}

	private getOrCreateQueue(commandName: string): Queue {
		const existingQueue = this.queues.get(commandName)
		if (existingQueue) {
			return existingQueue
		}

		const queue = new Queue(commandName, {
			connection: this.sharedConnection.options,
			defaultJobOptions: {
				removeOnComplete: true,
				removeOnFail: 1000,
				attempts: 3,
				backoff: {
					type: 'exponential',
					delay: 1000,
				},
			},
		})

		this.queues.set(commandName, queue)
		return queue
	}

	getCommandQueue(commandName: UseCases): Queue {
		const queue = this.queues.get(commandName)
		if (!queue) {
			throw new BaseError<BaseInfrastructureErrors>('COMMAND_QUEUE_NOT_FOUND')
		}
		return queue
	}

	async enqueueCommand<T extends Handler>(commandName: T['name'], input: T['input'], opts?: JobsOptions): Promise<void> {
		const tracer = trace.getTracer(Config.name)
		const span = tracer.startSpan(`enqueue ${commandName}`, { root: true })

		span.setAttribute('queue.command', commandName)
		span.setAttribute('queue.operation', 'enqueue')
		span.setAttribute('queue.input', describeValue(input))
		if (opts?.delay) span.setAttribute('queue.delay', opts.delay)
		if (opts?.priority) span.setAttribute('queue.priority', opts.priority)

		return context.with(trace.setSpan(context.active(), span), async () => {
			try {
				const queue = this.getOrCreateQueue(commandName)
				const job = await queue.add(commandName, input, opts)
				span.setAttribute('queue.job_id', job.id ?? 'unknown')
				span.setStatus({ code: SpanStatusCode.OK })
			} catch (error) {
				const err = error instanceof Error ? error : new Error(String(error))
				span.setStatus({ code: SpanStatusCode.ERROR, message: err.message })
				span.recordException(err)
				throw error
			} finally {
				span.end()
			}
		})
	}

	async registerCommandHandler(handler: Handler): Promise<void> {
		const existingWorker = this.workers.get(handler.name)
		if (existingWorker) {
			console.warn(`Worker for handler ${handler.name} already exists, skipping registration`)
			return
		}

		const queue = this.getOrCreateQueue(handler.name)

		const workerOptions: WorkerOptions = {
			connection: this.connection,
			concurrency: handler.concurrency ?? 1,
		}

		const worker = new Worker(
			queue.name,
			async (job: Job) => {
				const tracer = trace.getTracer(Config.name)
				const span = tracer.startSpan(`process ${handler.name}`, { root: true })

				span.setAttribute('queue.command', handler.name)
				span.setAttribute('queue.operation', 'process')
				span.setAttribute('queue.job_id', job.id ?? 'unknown')
				span.setAttribute('queue.attempt', job.attemptsMade + 1)
				span.setAttribute('queue.input', describeValue(job.data))

				return context.with(trace.setSpan(context.active(), span), async () => {
					try {
						const result = await handler.execute(job.data)
						span.setStatus({ code: SpanStatusCode.OK })
						return result
					} catch (error) {
						const err = error instanceof Error ? error : new Error(String(error))
						span.setStatus({ code: SpanStatusCode.ERROR, message: err.message })
						span.recordException(err)
						throw error
					} finally {
						span.end()
					}
				})
			},
			workerOptions,
		)

		worker.on('completed', (job: Job) => {
			console.log(`Job ${job.id} in queue ${handler.name} completed`)
		})

		worker.on('failed', (job: Job | undefined, error: Error) => {
			console.error(`Job ${job?.id} in queue ${handler.name} failed:`, error.message)
		})

		worker.on('error', (error: Error) => {
			console.error(`Worker error in queue ${handler.name}:`, error.message)
		})

import { BaseEntity } from './BaseEntity'
import type { ZodObject, ZodRawShape } from 'zod'

export class AggregateRoot<T extends ZodObject = ZodObject<ZodRawShape>> extends BaseEntity<T> {}

import { Id } from '../objects/Id'
import { ValueObject } from '../objects/ValueObject'
import { BaseError } from '../types/BaseError'
import type { BaseDomainEvent, DomainEventSchemaConstraint } from '../types/BaseDomainEvent'
import type { z, ZodObject, ZodRawShape, ZodType } from 'zod'
import type { BaseDomainErrors } from '../errors'

/** Widest accepted domain event shape — any subclass schema matching the constraint. */
type AnyDomainEvent = BaseDomainEvent<DomainEventSchemaConstraint>

export interface BaseEntityProps {
	id?: Id | string
	createdAt?: Date
	updatedAt?: Date
	version?: number
}

export abstract class BaseEntity<T extends ZodObject = ZodObject<ZodRawShape>> extends ValueObject {
	static schema?: ZodType
	private domainEvents: AnyDomainEvent[] = []

	id: Id = new Id()
	createdAt: Date = new Date()
	updatedAt: Date = new Date()
	version = 1

	constructor(props?: z.input<T> & BaseEntityProps) {
		super()
		if (!props) return

		const schema = (this.constructor as typeof BaseEntity).schema
		const result = schema?.safeParse(props)

		if (result && !result.success) {
			throw new BaseError<BaseDomainErrors>('INVALID_ENTITY', result.error.issues[0]?.message)
		}

		// Assign transformed domain props (schema applies .transform())
		Object.assign(this, result?.data ?? props)

		// Handle base entity props explicitly (id accepts string or Id)
		if (props.id != null) this.id = props.id instanceof Id ? props.id : new Id(props.id as string)
		if (props.createdAt != null) this.createdAt = props.createdAt
		if (props.updatedAt != null) this.updatedAt = props.updatedAt
		if (props.version != null) this.version = props.version
	}

	protected validate(): void {
		const schema = (this.constructor as typeof BaseEntity).schema
		if (!schema) return
		const result = schema.safeParse(this)
		if (!result.success) throw new BaseError(result.error.issues[0]!.message)
		Object.assign(this, result.data)
	}

	incrementVersion(): void {
		this.version++
		this.updatedAt = new Date()
	}

	/**
	 * Raise a domain event. Called from inside behavior methods when an
	 * aggregate transitions to a new state. Events accumulate until
	 * `pullDomainEvents()` is called (typically by a use case or handler
	 * that then persists them via `domainEventRepository.save`).
	 */
	protected addDomainEvent(event: AnyDomainEvent): void {
		this.domainEvents.push(event)
	}

	/**
	 * Drain and return all pending domain events. Clears the internal buffer.
	 * Callers iterate the returned array and persist each event via
	 * `domainEventRepository.save(event, tx)` inside the same transaction as
	 * the entity write.
	 */
	pullDomainEvents(): AnyDomainEvent[] {
		const events = this.domainEvents
		this.domainEvents = []
		return events
	}

	static transformed() {
		// biome-ignore lint/complexity/noThisInStatic: polymorphic this pattern — subclasses call BaseEntity.transformed() and `this` must resolve to the subclass constructor at runtime
		const Cls = this as unknown as { schema: ZodType; new (props: unknown): BaseEntity }
		return Cls.schema.input().transform((v: unknown) => new Cls(v))
	}
}

async publish(event: BaseEvent): Promise<void> {
	const payload = JSON.stringify(event.toJSON())
	await this.producer.xadd(streamKey(event.name), 'MAXLEN', '~', MAX_STREAM_LEN, '*', 'data', payload)
	this.notifyCallbacks(event.name, event)
}

async dispatch(event: BaseEvent): Promise<void> {
	// Fire-and-forget to match in-process dispatch semantics of the Kafka implementation.
	const handlers = this.handlerMap.get(event.name)
	if (!handlers) return

	for (const handler of handlers) {
		void tryCatchAsync(async () => handler.execute(event)).then(result => {
			if (!result.success) {
				console.error(`[Redis] Handler ${handler.name} failed for event ${event.name}:`, result.error)
			}
		})
	}
}

async execute<T extends Handler>(_handler: T['name'], _input: T['input']): Promise<T['output']> {
	throw new BaseError<BaseInfrastructureErrors>('NOT_IMPLEMENTED')
}

removeAllListeners(): void {
	this.handlerMap.clear()
	this.callbacks.clear()
	this.namedCallbacks.clear()
}

