import { describe, expect, it } from 'bun:test'
import { BaseDomainEvent } from './BaseDomainEvent'
import { AggregateRoot } from '../entities/AggregateRoot'

/** Minimal concrete event — no schema needed; the base carries entityId/version/sequence. */
class ThingHappenedEvent extends BaseDomainEvent {
	static override readonly name = 'test.thing.happened' as const
}

/** Test aggregate exposing the protected raise path. */
class TestAggregate extends AggregateRoot {
	raiseOne(label: string): void {
		this.addDomainEvent(new ThingHappenedEvent({ entityId: this.id.value, payload: { label } }))
	}

	raiseTwo(label: string): void {
		this.addDomainEvent(new ThingHappenedEvent({ entityId: this.id.value, payload: { label } }))
		this.addDomainEvent(new ThingHappenedEvent({ entityId: this.id.value, payload: { label } }))
	}

	pull() {
		return this.pullDomainEvents()
	}
}

const newAggregateId = (): string => new TestAggregate().id.value

describe('BaseDomainEvent — deterministic, time-independent id', () => {
	it('is stable across re-raises of the same logical event (retry-safe dedup key)', () => {
		const entityId = newAggregateId()

		// Two independent aggregate instances at the same loaded state — models a
		// command retried after a rollback. The raised event must get the SAME id.
		const first = new TestAggregate({ id: entityId })
		const second = new TestAggregate({ id: entityId })
		first.raiseOne('x')
		second.raiseOne('x')

		const [a] = first.pull()
		const [b] = second.pull()
		expect(a!.id).toBe(b!.id)
	})

	it('excludes wall-clock time from the seed once stamped', () => {
		const entityId = newAggregateId()
		const agg = new TestAggregate({ id: entityId })

		// Unstamped construction seeds on time (fallback); stamping reseeds on
		// (entityId, version, sequence). The id therefore changes on stamp, and the
		// stamped id no longer depends on `time`.
		const unstamped = new ThingHappenedEvent({ entityId, payload: { label: 'x' } })
		const unstampedId = unstamped.id

		agg.raiseOne('x')
		const [stamped] = agg.pull()

		expect(stamped!.version).toBe(agg.version)
		expect(stamped!.sequence).toBe(0)
		expect(stamped!.id).not.toBe(unstampedId)
	})

	it('disambiguates identical events raised in the same command via sequence', () => {
		const agg = new TestAggregate({ id: newAggregateId() })
		agg.raiseTwo('x')
		const [first, second] = agg.pull()

		expect(first!.sequence).toBe(0)
		expect(second!.sequence).toBe(1)
		// Same name + entityId + version + payload, different sequence → distinct ids.
		expect(first!.id).not.toBe(second!.id)
	})

	it('produces distinct ids for distinct payloads', () => {
		const entityId = newAggregateId()
		const a = new TestAggregate({ id: entityId })
		const b = new TestAggregate({ id: entityId })
		a.raiseOne('x')
		b.raiseOne('y')
		expect(a.pull()[0]!.id).not.toBe(b.pull()[0]!.id)
	})
})

