import { Id } from '../objects/Id'
import { z, type ZodTypeAny } from 'zod'

export const BaseEventSchema = z.object({
	name: z.string(),
	id: z.string(),
	time: z.iso.datetime(),
	payload: z.object(),
})

export abstract class BaseEvent<Payload extends ZodTypeAny = ZodTypeAny> {
	declare static readonly name: string
	readonly name: string
	readonly id: string
	readonly time: string
	readonly payload: z.infer<Payload>

	constructor(payload: z.infer<Payload>) {
		this.name = (this.constructor as { name: string }).name
		this.payload = payload
		this.time = new Date().toISOString()
		this.id = Id.fromSeed(...this.idSeedParts()).value
	}

	/**
	 * Parts hashed (UUIDv5) into the deterministic event id.
	 *
	 * Base events (e.g. integration events) keep `time` in the seed — preserving
	 * the original content-addressed behaviour. Domain events override this to
	 * seed on `(name, entityId, version, sequence)` instead, making the id stable
	 * across re-raises so it can serve as a dedup / ordering key — see
	 * `BaseDomainEvent`.
	 *
	 * Construction-order note: this is first invoked from the BaseEvent
	 * constructor, BEFORE a subclass body assigns its own fields, so it must
	 * tolerate those fields being undefined. Subclasses that widen the seed
	 * re-derive the id via `reseedId()` once their fields are set.
	 */
	protected idSeedParts(): string[] {
		return [this.name, this.time, JSON.stringify(this.payload)]
	}

	/** Re-derive `id` from the current seed parts. Called by subclasses once they set identity fields. */
	protected reseedId(): void {
		;(this as { id: string }).id = Id.fromSeed(...this.idSeedParts()).value
	}

	toJSON() {
		return Object.assign({ name: this.name }, this)
	}
}

