import { BaseEvent } from './BaseEvent'
import { z, type ZodObject, type ZodTypeAny } from 'zod'

export const BaseDomainEventSchema = z.object({
	// Both optional — some events (e.g. BillingWebhookReceivedEvent) carry a
	// computed entityId but no meaningful ownerId; pure "something happened"
	// events may have neither. Events that DO have entity/owner identity
	// (most domain events) still pass them at construction.
	entityId: z.string().optional(),
	ownerId: z.string().optional(),
	payload: z.object(),
})

export type DomainEventSchemaConstraint = ZodObject<{
	entityId: z.ZodOptional<z.ZodString>
	ownerId: z.ZodOptional<z.ZodString>
	payload: ZodTypeAny
}>

export abstract class BaseDomainEvent<EventSchema extends DomainEventSchemaConstraint = typeof BaseDomainEventSchema> extends BaseEvent<
	EventSchema['shape']['payload']
> {
	readonly entityId?: string
	readonly ownerId?: string
	/** Aggregate version this event was raised against. Stamped by `AggregateRoot.addDomainEvent`. */
	readonly version?: number
	/** 0-based position within the command that raised it — disambiguates same-type events in one command. */
	readonly sequence?: number

	constructor(data: z.infer<EventSchema>) {
		super(data.payload as z.infer<EventSchema['shape']['payload']>)
		this.entityId = data.entityId
		this.ownerId = data.ownerId
		// Rehydration may carry version/sequence; fresh events get them via stampSequence().
		this.version = (data as { version?: number }).version
		this.sequence = (data as { sequence?: number }).sequence
		this.reseedId()
	}

	/**
	 * Stamp the per-aggregate ordering coordinates and re-derive the stable id.
	 * Called by `AggregateRoot.addDomainEvent` with the aggregate's loaded version
	 * and the event's index within the current command. The pair `(version,
	 * sequence)` is deterministic across retries (same loaded state → same values),
	 * which is what makes the id a usable dedup key.
	 */
	stampSequence(version: number, sequence: number): void {
		;(this as { version?: number }).version = version
		;(this as { sequence?: number }).sequence = sequence
		this.reseedId()
	}

	protected override idSeedParts(): string[] {
		// Stamped, entity-identified events → stable, time-free id (dedup/ordering key).
		if (this.version != null && this.entityId != null) {
			return [this.name, this.entityId, `v${this.version}`, `s${this.sequence ?? 0}`, JSON.stringify(this.payload)]
		}
		// Not yet stamped, or no entity identity → fall back to `time` so distinct
		// occurrences don't collide (see plan S2).
		return [this.name, this.entityId ?? '', this.time, JSON.stringify(this.payload)]
	}
}

